const states={open:'Em aberto',overdue:'Vencida',pending:'Aguardando confirmação',paid:'Paga',cancel_pending:'Cancelamento em conferência',canceled:'Cancelada'};
const events={amend:'Cobrança corrigida',before_amend:'Dados anteriores à correção',created:'Cobrança registrada',boleto_attached:'Boleto disponibilizado',proof_received:'Comprovante recebido',paid:'Recebimento confirmado no banco',reject_proof:'Comprovante revisado',cancel_request:'Cancelamento solicitado',cancel_confirm:'Cancelamento confirmado no banco',reissue:'Boleto anterior substituído'};
const money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
export function createFinanceUI({api,esc,getState,openDialog,closeDialog,toast}){
 let active=false,admin=false,generation=0,data={receivables:[],clients:[]};
 const endpoint=(org='',files=false)=>'/api/portal/finance'+(files?'/files':'')+'?admin='+(admin?'1':'0')+'&org='+encodeURIComponent(org||getState().company.id);
 const field=(label,name,type='text',extra='')=>`<label class="p-field"><span>${label}</span><input name="${name}" type="${type}" required ${extra}></label>`;
 const button=(label,action,id='')=>`<button type="button" class="p-button secondary" data-finance-action="${action}" data-id="${esc(id)}">${label}</button>`;
 function page(isAdmin=false){admin=isAdmin;return `<section class="page-heading"><div><p class="overline">${admin?'ADMINISTRAÇÃO HELPU':'MINHA EMPRESA'}</p><h1>Financeiro</h1><p>${admin?'Organize cobranças, documentos e a conferência dos recebimentos.':'Seus boletos, vencimentos e comprovantes, em um só lugar.'}</p></div></section><section class="finance-panel"><p>${admin?'Emita o boleto no Sicredi e confira os dados antes de anexar. O registro na Helpu não movimenta dinheiro nem emite nota fiscal.':'O comprovante fica em análise até a confirmação do recebimento. Os dados bancários devem ser conferidos antes do pagamento.'}</p>${admin?button('Nova cobrança','new'):''}<div id="finance-list" role="status">Carregando financeiro…</div></section>`;}
 async function load(){const ticket=++generation;try{const next=await api(endpoint());if(!active||ticket!==generation)return;data=next;render();}catch(e){if(active&&ticket===generation)document.querySelector('#finance-list').innerHTML='<p role="alert">'+esc(e.message)+'</p>'+button('Tentar novamente','reload');}}
 function render(){const root=document.querySelector('#finance-list');if(!root)return;const counts=data.receivables.reduce((a,r)=>{if(r.providerMode==='test')return a;if(['open','overdue'].includes(r.displayState))a.open+=r.amountCents;if(r.displayState==='pending')a.pending+=r.amountCents;if(r.displayState==='paid')a.paid+=r.amountCents;return a;},{open:0,pending:0,paid:0});root.innerHTML=`<div class="company-grid">${[['Em aberto',counts.open],['Em conferência',counts.pending],[admin?'Recebido':'Pago',counts.paid]].map(([l,v])=>`<article class="company-tile"><small>${l}</small><h2>${money(v)}</h2></article>`).join('')}</div>${!admin?`<label class="checkline"><input id="finance-consent" type="checkbox" ${data.remindersEnabled?'checked':''}> Quero receber avisos financeiros no meu WhatsApp conectado.</label><p>Você pode desativar os avisos quando quiser. Seus boletos e vencimentos continuam disponíveis aqui.</p>`:''}<label class="p-field"><span>Filtrar cobranças</span><input id="finance-search" type="search" placeholder="${admin?'Empresa, descrição, referência ou situação':'Descrição, referência ou situação'}"></label><div class="finance-cards">${data.receivables.map(r=>{const name=data.clients.find(c=>c.id===r.orgId)?.name||'';return `<article class="p-card" data-finance-search="${esc((name+' '+r.description+' '+r.reference+' '+states[r.displayState]).toLowerCase())}"><p class="overline">${esc((r.providerMode==='test'?'TESTE STRIPE · ':'')+(name||r.competence))} · ${esc(states[r.displayState])}</p><h2>${esc(r.description)}</h2><p><strong>${money(r.amountCents)}</strong> · Vencimento: ${esc(r.dueDate.split('-').reverse().join('/'))}</p><p>Referência: ${esc(r.reference)}</p>${button('Abrir cobrança','detail',r.id)}</article>`;}).join('')||'<p>Nenhuma cobrança registrada.</p>'}</div><p id="finance-empty" hidden>Nenhuma cobrança corresponde à busca.</p>`;}
 function detail(r){const instrument=r.instrument;openDialog('Detalhes da cobrança',`<p class="overline">${esc(states[r.displayState])}</p><h2>${esc(r.description)}</h2><p><strong>${money(r.amountCents)}</strong> · Vencimento ${esc(r.dueDate)}</p><p>Competência: ${esc(r.competence)} · Pedido: ${esc(r.reference)}</p><h3>Condições acordadas</h3><p style="white-space:pre-wrap">${esc(r.terms)}</p>${instrument?`<h3>Boleto atual</h3><a class="p-button secondary" href="${esc(instrument.asset.url)}" target="_blank" rel="noopener">Baixar boleto PDF</a><label class="p-field"><span>Linha digitável</span><input readonly value="${esc(instrument.code)}"></label>${button('Copiar linha digitável','copy',r.id)}`:r.origin==='stripe'?'<p>Pagamento confirmado pelo Stripe. Consulte a contratação em Minha conta.</p>':'<p>O boleto ainda não foi anexado pela equipe.</p>'}<div class="finance-actions">${admin?(['open','pending'].includes(r.state)?button('Confirmar recebimento','paid',r.id)+button('Solicitar cancelamento','cancel_request',r.id):'')+(r.state==='open'?(instrument?button('Reemitir boleto','reissue',r.id):button('Anexar boleto','upload',r.id)+button('Corrigir cobrança','amend',r.id)):'')+(r.state==='pending'?button('Revisar comprovante','reject_proof',r.id):'')+(r.state==='cancel_pending'?button('Confirmar cancelamento no banco','cancel_confirm',r.id):''):['open','pending'].includes(r.state)?button('Enviar comprovante PDF','upload',r.id):''}</div><h3>Comprovantes</h3>${r.proofs.map(p=>`<p><a href="${esc(p.asset.url)}" target="_blank" rel="noopener">${esc(p.asset.name)}</a> · ${new Date(p.at).toLocaleString('pt-BR')}</p>`).join('')||'<p>Nenhum comprovante enviado.</p>'}<h3>Histórico</h3>${admin?'<p>Lembretes WhatsApp: '+(data.reminders||[]).filter(n=>n.receivable===r.id).map(n=>esc(({accepted:'Aceito pelo WhatsApp',uncertain:'Envio incerto — conferir manualmente',sending:'Em envio / conferir antes de repetir',skipped:'Não enviado'})[n.state]||n.state)+' ('+new Date(n.createdAt).toLocaleString('pt-BR')+')').join('; ')+'</p>':''}${r.history.map(h=>`<p><strong>${esc(events[h.event]||h.event)}</strong> · ${new Date(h.at).toLocaleString('pt-BR')}<br>${esc(!admin||['boleto_attached','proof_received'].includes(h.event)?'':h.detail||'')}</p>`).join('')}${admin&&r.instruments.length?'<h3>Boletos anteriores — não utilizar para pagamento</h3>'+r.instruments.map(i=>`<p><a href="${esc(i.asset.url)}" target="_blank" rel="noopener">${esc(i.asset.name)}</a> · ${esc(i.reason)}</p>`).join(''):''}`,true);}
 function create(){const key=crypto.randomUUID();openDialog('Nova cobrança',`<form id="finance-form"><label class="p-field"><span>Empresa</span><select name="orgId" required>${data.clients.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></label>${field('Descrição','description','text','maxlength="300"')}${field('Referência do pedido ou contrato','reference')}${field('Competência','competence','month')}${field('Valor em reais','amount','number','min="0.01" max="1000000" step="0.01"')}${field('Vencimento acordado','dueDate','date')}<label class="p-field"><span>Condições acordadas: pagamento, cancelamento, carência e eventual suspensão</span><textarea name="terms" required maxlength="2000"></textarea></label><p>Registre somente uma contratação já acordada. Este formulário não emite boleto nem ativa um plano.</p><button class="p-button primary">Registrar cobrança</button><p data-finance-error role="alert"></p></form>`,true);bind(async f=>api(endpoint(f.get('orgId')),'POST',{action:'create',requestKey:key,description:f.get('description'),reference:f.get('reference'),competence:f.get('competence'),dueDate:f.get('dueDate'),terms:f.get('terms'),amountCents:Math.round(Number(f.get('amount'))*100)}));}
 function operation(r,action){if(action==='amend'){openDialog('Corrigir cobrança',`<form id="finance-form">${field('Descrição','description','text',`value="${esc(r.description)}"`)}${field('Valor (R$)','amount','number',`min="0.01" step="0.01" value="${r.amountCents/100}"`)}${field('Vencimento','dueDate','date',`value="${esc(r.dueDate)}"`)}<label class="p-field"><span>Condições acordadas</span><textarea name="terms" required>${esc(r.terms)}</textarea></label>${field('Motivo da correção','note')}<button class="p-button primary">Salvar correção</button><p data-finance-error role="alert"></p></form>`);bind(f=>api(endpoint(r.orgId),'POST',{id:r.id,version:r.version,action,description:f.get('description'),amountCents:Math.round(Number(f.get('amount'))*100),dueDate:f.get('dueDate'),terms:f.get('terms'),note:f.get('note')}));return;}if(action==='upload'){openDialog(admin?'Anexar boleto':'Enviar comprovante',`<form id="finance-form">${admin?field('Linha digitável (47 ou 48 números)','code','text','pattern="[0-9]{47,48}"')+field('Referência do boleto no Sicredi','bankReference'):''}${field('Documento PDF de até 3 MB','file','file','accept="application/pdf"')}<p>${admin?'Confira beneficiário, valor e vencimento no documento antes de enviar.':'O envio suspende lembretes enquanto a equipe confere o recebimento.'}</p><button class="p-button primary">Enviar documento</button><p data-finance-error role="alert"></p></form>`);bind(async f=>{const file=f.get('file');if(!file.size||file.size>3*1024*1024)throw new Error('Escolha um PDF de até 3 MB.');const response=await fetch(endpoint(r.orgId,true),{method:'POST',credentials:'same-origin',headers:{'x-finance-id':r.id,'x-record-version':String(r.version),'x-file-name':encodeURIComponent(file.name),'x-payment-code':String(f.get('code')||''),'x-bank-reference':encodeURIComponent(String(f.get('bankReference')||''))},body:file});const result=await response.json();if(!response.ok)throw new Error(result.error||'Falha no envio.');return result;});return;}
  openDialog({paid:'Confirmar recebimento',reissue:'Reemitir boleto',cancel_request:'Solicitar cancelamento',cancel_confirm:'Confirmar cancelamento',reject_proof:'Revisar comprovante'}[action],`<form id="finance-form">${action==='paid'?field('Valor efetivamente recebido (R$)','amount','number',`min="0.01" step="0.01" value="${r.amountCents/100}"`)+field('Data do recebimento','paidDate','date'):''}${action==='reissue'?field('Novo vencimento','dueDate','date'):''}${field(action==='paid'?'Referência da liquidação no banco':'Justificativa / referência da conferência','note')}${['paid','cancel_confirm','reissue'].includes(action)?'<label class="checkline"><input name="bankConfirmed" type="checkbox" required> Conferi no banco '+(action==='paid'?'o recebimento efetivo.':'a baixa por cancelamento do boleto anterior.')+'</label>':''}<p>${action==='cancel_request'?'O cancelamento ficará pendente até a conferência no banco.':action==='reissue'?'Após confirmar, anexe o novo boleto nesta mesma cobrança.':action==='reject_proof'?'A cobrança voltará a ficar em aberto. O comprovante permanecerá no histórico.':''}</p><button class="p-button primary">Confirmar</button><p data-finance-error role="alert"></p></form>`);bind(f=>api(endpoint(r.orgId),'POST',{id:r.id,version:r.version,action,note:f.get('note'),amountCents:Math.round(Number(f.get('amount'))*100),paidDate:f.get('paidDate'),dueDate:f.get('dueDate'),bankConfirmed:f.get('bankConfirmed')==='on'}));
 }
 function bind(fn){const form=document.querySelector('#finance-form');form.addEventListener('submit',async e=>{e.preventDefault();const submit=form.querySelector('button');submit.disabled=true;try{await fn(new FormData(form));closeDialog();await load();toast('Financeiro atualizado.');}catch(err){form.querySelector('[data-finance-error]').textContent=err.message;}finally{submit.disabled=false;}});}
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-finance-action]');if(!b||!active)return;const action=b.dataset.financeAction,r=data.receivables.find(r=>r.id===b.dataset.id);try{if(action==='new')create();else if(action==='reload')await load();else if(r&&action==='detail')detail(r);else if(r&&action==='copy'){await navigator.clipboard.writeText(r.instrument.code);toast('Linha digitável copiada.');}else if(r)operation(r,action);}catch(err){toast(err.message,true);}});
 document.addEventListener('change',async e=>{if(!active||e.target.id!=='finance-consent')return;const el=e.target;el.disabled=true;try{await api(endpoint(),'POST',{action:'preferences',enabled:el.checked});data.remindersEnabled=el.checked;toast('Preferência salva.');}catch(err){el.checked=!el.checked;toast(err.message,true);}finally{el.disabled=false;}});
 document.addEventListener('input',e=>{if(!active||e.target.id!=='finance-search')return;let visible=0;for(const card of document.querySelectorAll('[data-finance-search]')){card.hidden=!card.dataset.financeSearch.includes(e.target.value.toLowerCase());if(!card.hidden)visible++;}document.querySelector('#finance-empty').hidden=visible>0;});
 return {page,mount(view){active=view==='finance';++generation;if(active)load();}};
}
